#!/usr/bin/env python3
"""
Round 164m (culprits), 4 October 2026. Needs round 163m.

Mother Earth basemap: continents full size at the coasts; less brown.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 164m (4 October)\n\nNeeds round 163m. No tiles patch. No app.js?v= bump.\n\n- Owner on 163m: the continents looked dwarfed and compressed, and too much\n  brown took away the dreamlike look.\n- Shrunk continents: every softening in motherPaintPixels (the plants mix,\n  the light washes, the colour blur) now averages land with land and water\n  with water only (mblur, weighted by the land and water masks). Before, the\n  dark sea was averaged into a band along every coast, so the land's edge\n  went dark and the continents read smaller. Coast glow gentler (0.26).\n- Less brown: plants from deep teal-spruce to a misty sage (MOTHER.pines),\n  bare ground and rock pale pearl and rose-sand to near white\n  (MOTHER.stone), a lighter tone curve; towns, roads and buildings in soft\n  warm greys instead of umber; the sheet a dark blue-teal. Sky unchanged.\n- Checked on sample world-view satellite tiles in Chromium, side by side with\n  the original: coasts where the picture has them. Not seen live.\n"]
DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round164m: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 163m" not in h.read_text(encoding="utf-8"):
        sys.exit("round164m: round 163m must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round164m: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round164m: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round164m: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
